<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;$error='';$id=(int)($_GET['id']??0);$c=$id?one('SELECT * FROM content WHERE id=?',[$id]):null;if($id&&!$c){http_response_code(404);exit('Conteúdo não encontrado.');}if(is_post()){verify_csrf();try{$title=input('title',180);$body=input('body',15000);$kind=input('kind',30);$version=input('version',30);$link=safe_url(input('link',1000));$image=safe_url(input('image_url',1000));if($title===''||!in_array($kind,['project','news','testimonial','demo'],true))throw new InvalidArgumentException('Título ou tipo inválido.');if(!in_array($version,['','97d','s2','s6','s19'],true))throw new InvalidArgumentException('Versão inválida.');$published=isset($_POST['published'])?1:0;if($c)run('UPDATE content SET kind=?,title=?,body=?,version=?,link=?,image_url=?,published=? WHERE id=?',[$kind,$title,$body,$version,$link,$image,$published,$id]);else{run('INSERT INTO content (kind,title,body,version,link,image_url,published,created_at) VALUES (?,?,?,?,?,?,?,?)',[$kind,$title,$body,$version,$link,$image,$published,date('Y-m-d H:i:s')]);$id=(int)db()->lastInsertId();}audit('conteudo_salvo','Conteúdo #'.$id);flash('Conteúdo salvo. As publicações já aparecem no site.');go('admin/conteudo.php?id='.$id);}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}require ROOT.'/includes/panel.php';?><div class="toolbar"><h1>CMS e conteúdo.</h1><a class="primary btn" href="<?=e(url('admin/conteudo.php?novo=1'))?>">+ Nova publicação</a></div><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;if($c||isset($_GET['novo'])):?><form class="content-form" method="post"><?php csrf();?><div class="grid-two"><label class="field">Tipo<select name="kind"><?php foreach(['project'=>'Portfólio / projeto','news'=>'Notícia','testimonial'=>'Depoimento','demo'=>'Demonstração'] as $k=>$v):?><option value="<?=$k?>" <?=($c['kind']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="field">Título / nome do autor<input name="title" required maxlength="180" value="<?=e($c['title']??'')?>"></label><label class="field">Versão<select name="version"><?php foreach([''=>'Geral','97d'=>'97d + 99i','s2'=>'Season 2','s6'=>'Season 6','s19'=>'Season 19+'] as $k=>$v):?><option value="<?=$k?>" <?=($c['version']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="field">URL HTTPS da demonstração (opcional)<input type="url" name="link" maxlength="1000" value="<?=e($c['link']??'')?>"></label><label class="field">URL HTTPS da captura / capa (opcional)<input type="url" name="image_url" maxlength="1000" value="<?=e($c['image_url']??'')?>"></label></div><label class="field">Texto (sem HTML)<textarea name="body" maxlength="15000"><?=e($c['body']??'')?></textarea></label><label class="check"><input type="checkbox" name="published" <?=($c['published']??0)?'checked':''?>>Publicar no site</label><p class="small">Cadastre somente projetos e depoimentos reais com autorização, ou identifique explicitamente como conceito demonstrativo. Para retirar uma publicação, desmarque Publicar.</p><button class="primary">Salvar publicação</button></form><?php else:?><div class="table-wrap"><table><tr><th>Título</th><th>Tipo</th><th>Publicação</th><th>Ação</th></tr><?php foreach(rows('SELECT * FROM content ORDER BY id DESC LIMIT 300') as $c):?><tr><td><?=e($c['title'])?></td><td><?=e($c['kind'])?></td><td><?=$c['published']?'Publicada':'Rascunho'?></td><td><a href="<?=e(url('admin/conteudo.php?id='.$c['id']))?>">Editar ↗</a></td></tr><?php endforeach;?></table></div><?php endif;require ROOT.'/includes/endpanel.php';?>
